def build_doc_row(overrides: dict = None) -> str:
    """按模板顺序输出全部 190 字段（扁平无换行），overrides 按 key 覆写值。"""
    ov = {k: (v if v is not None else '') for k, v in (overrides or {}).items()}
    out = []
    for k, v in DOC_ROW_DEFAULT.items():
        out.append(f'<{k}>{ov.get(k, v)}</{k}>')
    for k, v in ov.items():
        if k not in DOC_ROW_DEFAULT:
            out.append(f'<{k}>{v}</{k}>')
    return ''.join(out)


